521: export function detectTripPlanRequest(text: string): {
522:   intent: boolean;
523:   days: number;
524:   travelers: number;
525:   budget: number | null;
526: } {
527:   const normalized = String(text || "").toLowerCase();
528:   const tripWord =
529:     /\b(viaje|viajar|plan|planear|planea|planifica|itinerario|ruta|recorrido|tour|dias?|días?)\b/i.test(
530:       normalized,
531:     );
532:   const planningWord =
533:     /\b(plan|planear|planea|planifica|itinerario|arma|armar|organiza|recomienda|sugiere)\b/i.test(
534:       normalized,
535:     );
536:   const explicitDays = normalized.match(/(\d{1,2})\s*(d[ií]as?|days?)\b/i);
537:   const explicitTravelers = normalized.match(
538:     /(\d{1,2})\s*(personas?|viajeros?|adultos?|travelers?|pax)\b/i,
539:   );
540:   const budgetMatch = normalized.match(
541:     /(?:presupuesto|budget|hasta|maximo|máximo)\s*(?:de|:)?\s*\$?\s*([\d.,]{4,})/i,
542:   );
543:   const budget = budgetMatch
544:     ? Number(budgetMatch[1].replace(/[.,]/g, "")) || null
545:     : null;
546: 
547:   return {
548:     intent: tripWord && (planningWord || explicitDays !== null || /\bviaj/i.test(normalized)),
549:     days: explicitDays ? Math.min(Math.max(Number(explicitDays[1]), 1), 7) : 3,
550:     travelers: explicitTravelers
551:       ? Math.min(Math.max(Number(explicitTravelers[1]), 1), 10)
552:       : 2,
553:     budget,
554:   };
555: }
