564:       normalized,
565:     ) && /\b(ruta|recorrido|itinerario|plan|viaje)\b/.test(normalized)
566:   ) || /\b(s[ií],?\s+confirmo|dale,?\s+establece|hazlo)\b/.test(normalized);
