const signature = sha256(`${reference}${amountInCents}${currency}${expiration}${integrity}`);
const url = new URL("https://checkout.wompi.co/p/");
url.searchParams.set("public-key", publicKey);
url.searchParams.set("currency", currency);
url.searchParams.set("amount-in-cents", String(amountInCents));
url.searchParams.set("reference", reference);
url.searchParams.set("signature:integrity", signature);
url.searchParams.set("redirect-url", redirectUrl);
url.searchParams.set("expiration-time", expiration);
return {url: url.toString(), mode:"signed", sandbox: publicKey.startsWith("pub_test_")}
```
Wompi public test keys start `pub_test_`; production `pub_prod_`. Good.
- Should we include customer-data:email? Avoid PII; don't.

`verifyWompiEventChecksum` pure:
```
export function computeWompiEventChecksum(payload:any, secret:string): string | null {
 const props = payload?.signature?.properties;
 if (!Array.isArray(props)) return null;
 const values = props.map((path:string)=> getPath(payload.data, path));
 if (values.some(v => v===undefined || v===null)) return null;
 const timestamp = payload.timestamp;
 return sha256(values.map(String).join("") + String(timestamp) + secret);
}
export function verifyWompiEventChecksum(payload, received, secret) {
 const expected = compute...; return expected && timingSafeEqualHex(expected, received)
}
